import { Ticket } from '../models/index.js';

// Adds sold / remaining / percent to lotteries (one query for all of them)
export async function withStats(lotteries) {
  const list = Array.isArray(lotteries) ? lotteries : [lotteries];
  const ids = list.map((l) => l._id);
  const rows = await Ticket.aggregate([
    { $match: { lottery: { $in: ids } } },
    { $group: { _id: '$lottery', n: { $sum: 1 } } },
  ]);
  const map = new Map(rows.map((r) => [String(r._id), r.n]));
  const out = list.map((l) => {
    const sold = map.get(String(l._id)) || 0;
    return {
      id: String(l._id),
      title: l.title,
      carName: l.carName,
      carColor: l.carColor,
      imageUrl: l.imageUrl,
      ticketPrice: l.ticketPrice,
      totalTickets: l.totalTickets,
      endsAt: l.endsAt,
      featured: l.featured,
      status: l.status,
      createdAt: l.createdAt,
      winnerNumber: l.winnerNumber ?? null,
      sold,
      remaining: Math.max(l.totalTickets - sold, 0),
      percent: Math.round((sold / l.totalTickets) * 100),
    };
  });
  return Array.isArray(lotteries) ? out : out[0];
}

export const publicBank = (b) => ({
  id: String(b._id),
  bankName: b.bankName,
  accountName: b.accountName,
  accountNumber: b.accountNumber,
});
